{
  "table": {
    "name": "Free or Reduced Price Meals (FRPM) eligibility data for California public schools, 2014-15",
    "purpose": "California Department of Education FRPM file: one row per public school (plus 45 district-office rows), keyed by the 14-digit CDS (County-District-School) code. For each school it reports enrollment and the counts and shares of students eligible for free meals and for free or reduced-price meals under the National School Lunch Program, on two reporting bases (grades K-12 and ages 5-17), along with school attributes: county/district/school identification, district type, grade span, educational option type, school type, charter status/number/funding type, NSLP provision status, and a CALPADS Fall 1 certification flag. All rows are academic year 2014-2015. The CDSCode is the natural key to the companion tables (schools, satscores)."
  },
  "columns": {
    "2013-14 CALPADS Fall 1 Certification Status": {
      "role": "boolean",
      "name": "2013-14 CALPADS Fall 1 certification status",
      "description": "Certification status of the school's 2013-14 CALPADS Fall 1 submission (Fall 1 is the October enrollment census in CALPADS, California's longitudinal student data system). Constant value 1 for all 9,986 rows; 1 presumably means the submission was certified. Because the column never varies, the exact encoding of the value cannot be verified from the data alone.",
      "status": "resolved"
    },
    "Academic Year": {
      "role": "date",
      "name": "Academic year",
      "description": "School year the record covers, formatted 'YYYY-YYYY'. Constant '2014-2015' - this file contains only 2014-15 data.",
      "status": "resolved"
    },
    "CDSCode": {
      "role": "identifier",
      "name": "CDS code (County-District-School identifier)",
      "description": "Unique 14-digit CDS code identifying the school: 2-digit County Code + 5-digit District Code + 7-digit School Code (verified in sample rows, e.g. 09|61853|0934554 = El Dorado County, El Dorado Union High district, Independence Continuation). Primary key of the table; one row per school (or district office).",
      "status": "resolved"
    },
    "Charter Funding Type": {
      "role": "category",
      "name": "Charter school funding type",
      "description": "How a charter school receives state funding: 'Directly funded' (funds flow directly from the state to the charter, 838 rows) or 'Locally funded' (funds flow through the authorizing district, 328 rows); 'Not in CS funding model' for the single charter outside the charter-school funding model. Null for the ~88% of rows that are not charter schools.",
      "status": "resolved"
    },
    "Charter School (Y/N)": {
      "role": "boolean",
      "name": "Charter school indicator",
      "description": "Binary flag: 1 = the school is a charter school (1,167 rows), 0 = not a charter (8,774 rows); a handful of rows are null.",
      "status": "resolved"
    },
    "Charter School Number": {
      "role": "identifier",
      "name": "Charter school number",
      "description": "State-assigned charter school number (4 characters, numeric or alphanumeric, e.g. '0756', '00D2'). Populated only for charter schools; null for non-charters (null rate 0.883 matches the non-charter share).",
      "status": "resolved"
    },
    "County Code": {
      "role": "identifier",
      "name": "County code",
      "description": "Two-digit California county code (01-58), the first two digits of the CDS code; e.g. 19 = Los Angeles, 37 = San Diego, 30 = Orange, 36 = San Bernardino, 33 = Riverside.",
      "status": "resolved"
    },
    "County Name": {
      "role": "category",
      "name": "County name",
      "description": "Name of the California county in which the school/district is located; pairs with County Code (58 counties).",
      "status": "resolved"
    },
    "District Code": {
      "role": "identifier",
      "name": "District code",
      "description": "Five-digit district (local educational agency) code, digits 3-7 of the CDS code; e.g. 64733 = Los Angeles Unified, 68338 = San Diego Unified.",
      "status": "resolved"
    },
    "District Name": {
      "role": "category",
      "name": "District name",
      "description": "Name of the school district / local educational agency the school belongs to; pairs with District Code (1,012 distinct codes vs 1,000 distinct names, so a few districts share a name or have multiple codes).",
      "status": "resolved"
    },
    "District Type": {
      "role": "category",
      "name": "District type",
      "description": "Type of the district/local educational agency: Unified School District, Elementary School District, High School District, County Office of Education (COE), State Board of Education, Non-School Locations, etc.",
      "status": "resolved"
    },
    "Educational Option Type": {
      "role": "category",
      "name": "Educational option type",
      "description": "CDE educational option/program type of the school: Traditional, Continuation School, Alternative School of Choice, Community Day School, Special Education School, Juvenile Court School, Home and Hospital, Opportunity School, State Special School, etc.",
      "status": "resolved"
    },
    "Enrollment (Ages 5-17)": {
      "role": "numeric",
      "name": "Enrollment, ages 5-17",
      "description": "Number of students enrolled at the school who are aged 5-17; the age-based denominator for the ages-5-17 meal-eligibility figures.",
      "status": "resolved"
    },
    "Enrollment (K-12)": {
      "role": "numeric",
      "name": "Enrollment, grades K-12",
      "description": "Number of students enrolled in grades K-12 at the school; the grade-based denominator for the K-12 meal-eligibility figures.",
      "status": "resolved"
    },
    "FRPM Count (Ages 5-17)": {
      "role": "numeric",
      "name": "Free/reduced-price meal eligible count, ages 5-17",
      "description": "Number of enrolled students aged 5-17 eligible for free or reduced-price meals under the National School Lunch Program; equals the free-meal count plus reduced-price-eligible students (e.g. row 1: 63 FRPM vs 54 free).",
      "status": "resolved"
    },
    "FRPM Count (K-12)": {
      "role": "numeric",
      "name": "Free/reduced-price meal eligible count, grades K-12",
      "description": "Number of enrolled K-12 students eligible for free or reduced-price meals under the NSLP (free-meal count plus reduced-price-eligible students).",
      "status": "resolved"
    },
    "Free Meal Count (Ages 5-17)": {
      "role": "numeric",
      "name": "Free meal eligible count, ages 5-17",
      "description": "Number of enrolled students aged 5-17 eligible for free meals under the NSLP (family income within the free-meal threshold); a subset of the FRPM count.",
      "status": "resolved"
    },
    "Free Meal Count (K-12)": {
      "role": "numeric",
      "name": "Free meal eligible count, grades K-12",
      "description": "Number of enrolled K-12 students eligible for free meals under the NSLP; a subset of the K-12 FRPM count.",
      "status": "resolved"
    },
    "High Grade": {
      "role": "category",
      "name": "Highest grade offered",
      "description": "Highest grade level served by the school: K or 1-12 (12 is most common). The rare value 13 most likely denotes ungraded/adult-level programs in the CDE grade coding; this cannot be confirmed from the data alone.",
      "status": "resolved"
    },
    "IRC": {
      "role": "boolean",
      "name": "Independently reporting charter flag",
      "description": "Binary flag (0/1), 1 for 729 schools. In the CDE FRPM file layout IRC stands for 'Independently Reporting Charter' - 1 would mark charter schools that report their data separately from their authorizing district rather than through it. The data is consistent with this reading (a 0/1 flag whose null pattern matches the charter-indicator column, set on a subset smaller than the 1,167 charter schools), but the acronym is not explained anywhere in the data, so it cannot be confirmed here.",
      "status": "tentative"
    },
    "Low Grade": {
      "role": "category",
      "name": "Lowest grade offered",
      "description": "Lowest grade level served by the school: P = preschool, K = kindergarten, 1-12 = first through twelfth grade.",
      "status": "resolved"
    },
    "NSLP Provision Status": {
      "role": "category",
      "name": "National School Lunch Program provision status",
      "description": "Special NSLP meal-counting provision the school operates under: Provision 1, Provision 2, Provision 3, Breakfast Provision 2, CEP (Community Eligibility Provision), or Multiple Provision Types. Null for the ~82% of schools not operating under a special provision.",
      "status": "resolved"
    },
    "Percent (%) Eligible FRPM (Ages 5-17)": {
      "role": "numeric",
      "name": "Share of students eligible for free/reduced-price meals, ages 5-17",
      "description": "FRPM Count (Ages 5-17) divided by Enrollment (Ages 5-17), stored as a fraction between 0 and 1 (e.g. 46/73 = 0.6301) despite the '%' in the column name.",
      "status": "resolved"
    },
    "Percent (%) Eligible FRPM (K-12)": {
      "role": "numeric",
      "name": "Share of students eligible for free/reduced-price meals, grades K-12",
      "description": "FRPM Count (K-12) divided by Enrollment (K-12), stored as a fraction between 0 and 1 (e.g. 63/102 = 0.6176).",
      "status": "resolved"
    },
    "Percent (%) Eligible Free (Ages 5-17)": {
      "role": "numeric",
      "name": "Share of students eligible for free meals, ages 5-17",
      "description": "Free Meal Count (Ages 5-17) divided by Enrollment (Ages 5-17), stored as a fraction between 0 and 1 (e.g. 40/73 = 0.5479).",
      "status": "resolved"
    },
    "Percent (%) Eligible Free (K-12)": {
      "role": "numeric",
      "name": "Share of students eligible for free meals, grades K-12",
      "description": "Free Meal Count (K-12) divided by Enrollment (K-12), stored as a fraction between 0 and 1 (e.g. 54/102 = 0.5294).",
      "status": "resolved"
    },
    "School Code": {
      "role": "identifier",
      "name": "School code",
      "description": "Seven-digit school code, the last seven digits of the CDS code; '0000000' marks the 45 district-office rows that have no school.",
      "status": "resolved"
    },
    "School Name": {
      "role": "category",
      "name": "School name",
      "description": "Name of the school (e.g. 'Monterey Trail High', 'Independence Continuation'); 'District Office' for the 45 district-level rows. Names are not unique statewide (33 'Lincoln Elementary', 28 'Washington Elementary').",
      "status": "resolved"
    },
    "School Type": {
      "role": "category",
      "name": "School type",
      "description": "CDE school level/type category: Elementary Schools (Public), High Schools (Public), Intermediate/Middle Schools (Public), Continuation High Schools, Alternative Schools of Choice, K-12 Schools (Public), Junior High Schools (Public), etc.",
      "status": "resolved"
    }
  }
}
